<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useRoute} from 'vue-router'
import {api,requestId as newRequestId,contextVersion,isCancelled} from '../lib/api'
import {useResource,loadStudents,notify,studentOptions,subjectOptions} from '../lib/ui'
import {attachmentUrl} from '../mobile/endpoints'
import {serviceBase} from '../mobile/platform'
import type {Attachment} from '../lib/types'
import PageHeader from '../components/PageHeader.vue'
import SoftSelect from '../components/SoftSelect.vue'
import AppIcon from '../components/AppIcon.vue'
import AttachmentList from '../components/AttachmentList.vue'
import LoadState from '../components/LoadState.vue'
const route=useRoute(),studentId=ref<string|number>(String(route.query.studentId||'')),subject=ref('数学'),kind=ref(String(route.query.kind||'MISTAKE')),question=ref(''),photo=ref<Attachment|null>(null),busy=ref(false),error=ref(''),note=ref(''),saved=ref(false)
const students=useResource(loadStudents),child=computed(()=>students.data.value?.find(s=>s.id===Number(studentId.value)))
const controller=new AbortController();onBeforeUnmount(()=>controller.abort())
let requestId='',fingerprint=''
watch([studentId,contextVersion],()=>{photo.value=null;question.value='';note.value='';error.value='';requestId='';saved.value=false})
async function capture(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0],student=child.value;if(!file||!student)return;const version=contextVersion.value;busy.value=true;error.value='';saved.value=false;try{if(!file.type.startsWith('image/'))throw new Error('请选择题目照片');const data=new FormData();data.append('file',file);photo.value=await api<Attachment>('/files',{method:'POST',body:data,campusId:student.campusId,signal:controller.signal});const result=await api<{status:string;text:string;message:string}>('/teaching-capture/recognize',{method:'POST',body:{studentId:student.id,photoFileId:photo.value.id},signal:controller.signal});question.value=result.text;note.value=result.message}catch(e){if(version===contextVersion.value&&!isCancelled(e)&&!controller.signal.aborted)error.value=(e as Error).message}finally{if(version===contextVersion.value)busy.value=false;input.value=''}}
async function save(){if(!child.value||!photo.value||busy.value)return;const version=contextVersion.value;const body={studentId:child.value.id,photoFileId:photo.value.id,kind:kind.value,subject:subject.value,questionText:question.value.trim()};const current=JSON.stringify(body);if(!requestId||fingerprint!==current){requestId=newRequestId();fingerprint=current}busy.value=true;error.value='';try{await api('/teaching-capture/save',{method:'POST',body:{...body,requestId},signal:controller.signal});if(version===contextVersion.value&&!controller.signal.aborted){saved.value=true;notify(kind.value==='MISTAKE'?'题目已加入错题本，可生成PDF打印':'作业照片已提交，等待批改')}}catch(e){if(version===contextVersion.value&&!isCancelled(e))error.value=(e as Error).message}finally{if(version===contextVersion.value)busy.value=false}}
</script>
<template><PageHeader title="拍照录题" subtitle="拍清题目，校对后保存，把录入留给更简单的步骤。" /><LoadState :loading="students.loading.value" :error="students.error.value" @retry="students.refresh"><section class="panel capture-panel"><div class="capture-steps"><span>1 拍照</span><span>2 校对题目</span><span>3 确认保存</span></div><label class="field"><span>选择孩子</span><SoftSelect v-model="studentId" :disabled="busy" :options="studentOptions(students.data.value||[])" placeholder="请选择学生" /></label><div class="capture-fields"><label class="field"><span>学科</span><SoftSelect v-model="subject" :disabled="busy" :options="subjectOptions" /></label><label class="field"><span>保存到</span><SoftSelect v-model="kind" :disabled="busy" :options="[{value:'MISTAKE',label:'错题本'},{value:'HOMEWORK',label:'作业记录'}]" /></label></div><div class="capture-camera"><AppIcon name="ScanLine" :size="34" /><strong>{{photo?'照片已上传，可重新拍摄':'把题目放在画面中央'}}</strong><p>每次拍一道题，尽量拍清完整题干。</p><div class="row-actions"><label class="btn primary">拍照<input type="file" accept="image/*" capture="environment" :disabled="busy||!child" @change="capture" /></label><label class="btn secondary">从相册选择<input type="file" accept="image/*" :disabled="busy||!child" @change="capture" /></label></div></div><img v-if="photo" class="capture-preview" :src="attachmentUrl(serviceBase,photo.url)" alt="待校对的题目照片" /><AttachmentList v-if="photo" :files="[photo]" /><p v-if="note" class="capture-note">{{note}}</p><label class="field"><span>校对题目（照片清楚时可留空）</span><textarea v-model="question" :disabled="busy" :maxlength="kind==='MISTAKE'?10000:2000" rows="7" placeholder="可按照片手工填写题目；知识点与错误原因可稍后补充。" /></label><p v-if="error" class="form-error" role="alert">{{error}}</p><button class="btn primary" :disabled="busy||!photo||!child||saved" @click="save">{{busy?'正在处理…':saved?'已保存':'确认并保存'}}</button><div v-if="saved" class="capture-links"><RouterLink :to="kind==='MISTAKE'?`/mistakes?studentId=${studentId}`:`/homework?studentId=${studentId}`">{{kind==='MISTAKE'?'查看错题并打印':'查看作业记录'}} ›</RouterLink><button class="text-btn" @click="photo=null;question='';note='';saved=false">继续拍下一题</button></div></section></LoadState></template>
<style scoped>.capture-preview{display:block;width:100%;max-height:440px;object-fit:contain;border-radius:18px;background:#f5f5f7;margin:18px 0}.capture-panel{padding:26px;max-width:780px;margin:auto}.capture-steps{display:flex;justify-content:space-between;color:var(--text-secondary);font-size:13px;margin-bottom:26px}.capture-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.capture-camera{background:#f2f6fc;border:1px dashed #cbd7ea;border-radius:22px;display:flex;flex-direction:column;align-items:center;gap:12px;padding:30px 15px;margin:22px 0}.capture-camera p,.capture-note{font-size:13px;line-height:1.8;color:var(--text-secondary)}.capture-note{background:#fff5e8;border-radius:15px;padding:16px;margin:18px 0}.capture-camera input{display:none}.capture-links{display:flex;justify-content:space-between;gap:15px;margin-top:20px}.capture-panel textarea{width:100%}@media(max-width:600px){.capture-panel{padding:20px}.capture-fields{grid-template-columns:1fr}.capture-camera .row-actions{flex-wrap:wrap;justify-content:center}}</style>
